package com.foodordering.food;
import java.util.*; import org.springframework.cache.annotation.*; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.web.server.ResponseStatusException;
@Service public class FoodService {private final FoodRepository foods;private final RestaurantRepository restaurants; FoodService(FoodRepository f,RestaurantRepository r){foods=f;restaurants=r;} FoodResponse dto(Food f){return new FoodResponse(f.foodId,f.foodName,f.price,f.category,f.availability,f.restaurant.restaurantId);} @Cacheable(value="foods",key="#id") public FoodResponse get(Long id){System.out.println("CACHE MISS - loading food "+id+" from MySQL");return dto(foods.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Food "+id+" not found")));} List<FoodResponse> list(String category,Long restaurant,boolean all){return foods.findAll().stream().filter(x->category==null||category.equalsIgnoreCase(x.category)).filter(x->restaurant==null||restaurant.equals(x.restaurant.restaurantId)).filter(x->all||x.availability).map(this::dto).toList();} FoodResponse create(FoodRequest x){Restaurant r=restaurants.findById(x.restaurantId()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Restaurant not found"));Food f=Food.of(x.foodName(),x.price(),x.category(),r);if(x.availability()!=null)f.availability=x.availability();return dto(foods.save(f));} @CachePut(value="foods",key="#id") public FoodResponse update(Long id,FoodRequest x){Food f=foods.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Food not found"));Restaurant r=restaurants.findById(x.restaurantId()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Restaurant not found"));f.foodName=x.foodName();f.price=x.price();f.category=x.category();f.restaurant=r;if(x.availability()!=null)f.availability=x.availability();return dto(foods.save(f));} @CacheEvict(value="foods",key="#id") public void delete(Long id){if(!foods.existsById(id))throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Food not found");foods.deleteById(id);} RestaurantResponse restaurant(RestaurantRequest x){Restaurant r=restaurants.save(Restaurant.of(x.restaurantName(),x.location()));return new RestaurantResponse(r.restaurantId,r.restaurantName,r.location);} List<RestaurantResponse> restaurants(){return restaurants.findAll().stream().map(r->new RestaurantResponse(r.restaurantId,r.restaurantName,r.location)).toList();}}
